 ORDER BY TABLE_NAME,REFERENCED_TABLE_NAME;
SELECT TABLE_NAME,VIEW_DEFINITION FROM information_schema.VIEWS
 WHERE TABLE_SCHEMA=DATABASE() ORDER BY TABLE_NAME;
SELECT ROUTINE_TYPE,ROUTINE_NAME FROM information_schema.ROUTINES
 WHERE ROUTINE_SCHEMA=DATABASE() ORDER BY ROUTINE_TYPE,ROUTINE_NAME;
SELECT EVENT_NAME,STATUS FROM information_schema.EVENTS WHERE EVENT_SCHEMA=DATABASE();
SELECT TRIGGER_NAME,EVENT_OBJECT_TABLE FROM information_schema.TRIGGERS WHERE TRIGGER_SCHEMA=DATABASE();
SELECT ems_id,COUNT(*) AS devices FROM com_device_info GROUP BY ems_id;
SELECT ems_id,COUNT(*) AS ping_rows,MAX(reg_dt) AS latest FROM raw_ping_log GROUP BY ems_id;
SELECT ems_id,COUNT(*) AS usage_rows,MAX(reg_dt) AS latest FROM raw_usage_log GROUP BY ems_id;
SELECT ems_id,COUNT(*) AS fault_rows,MAX(event_dt) AS latest FROM raw_event_log GROUP BY ems_id;
